begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into auth.users(id,aud,role,email) values('af444444-4444-4444-8444-444444444444','authenticated','authenticated','scope-owner@example.test');
set local role authenticated;
set local request.jwt.claims='{"sub":"af444444-4444-4444-8444-444444444444","role":"authenticated"}';
do $$ begin
 perform set_config('test.sw',public.create_workspace('Scope Studio')::text,true);
 perform set_config('test.sa',(select id::text from public.agents where workspace_id=current_setting('test.sw')::uuid and is_default),true);
 perform set_config('test.sb',public.create_agent(current_setting('test.sw')::uuid,'Sales','Help with sales.','en')::text,true);
 perform set_config('test.k1',public.save_business_knowledge(current_setting('test.sw')::uuid,null,'custom_note','Approved service','Only the approved service.',null,'','','',null)::text,true);
 perform set_config('test.k2',public.save_business_knowledge(current_setting('test.sw')::uuid,null,'custom_note','Unrelated service','An unrelated service.',null,'','','',null)::text,true);
 perform set_config('test.k3',public.save_business_knowledge(current_setting('test.sw')::uuid,null,'custom_note','Draft service','Unpublished information.',null,'','','',null)::text,true);
 perform set_config('test.sother',public.create_workspace('Other Scope Studio')::text,true);
 perform set_config('test.kforeign',public.save_business_knowledge(current_setting('test.sother')::uuid,null,'custom_note','Other workspace','Private workspace information.',null,'','','',null)::text,true);
 perform set_config('test.svec','['||'1,'||repeat('0,',1534)||'0]',true);
end $$;
select extensions.throws_ok($$select public.set_agent_knowledge_scope(current_setting('test.sw')::uuid,current_setting('test.sb')::uuid,'selected',array[current_setting('test.kforeign')::uuid])$$,'22023',null,'Cross-workspace Knowledge binding rejected even for owner of both');
select extensions.throws_ok($$select public.set_agent_knowledge_scope(current_setting('test.sother')::uuid,current_setting('test.sb')::uuid,'selected','{}')$$,'42501',null,'Cross-workspace Agent reference rejected');
select public.set_agent_knowledge_scope(current_setting('test.sw')::uuid,current_setting('test.sb')::uuid,'selected',array[current_setting('test.k1')::uuid,current_setting('test.k3')::uuid]);
select extensions.is((select count(*)::integer from public.match_agent_knowledge(current_setting('test.sw')::uuid,current_setting('test.sb')::uuid,current_setting('test.svec')::extensions.vector)),0,'Bindings cannot publish Draft Knowledge');
set local role service_role;
set local request.jwt.claims='{"role":"service_role"}';
select public.publish_knowledge_item('af444444-4444-4444-8444-444444444444',current_setting('test.sw')::uuid,current_setting('test.k1')::uuid,1,current_setting('test.svec')::extensions.vector);
select public.publish_knowledge_item('af444444-4444-4444-8444-444444444444',current_setting('test.sw')::uuid,current_setting('test.k2')::uuid,1,current_setting('test.svec')::extensions.vector);
set local role authenticated;
set local request.jwt.claims='{"sub":"af444444-4444-4444-8444-444444444444","role":"authenticated"}';
select extensions.is((select count(*)::integer from public.match_agent_knowledge(current_setting('test.sw')::uuid,current_setting('test.sa')::uuid,current_setting('test.svec')::extensions.vector)),2,'All mode retrieves all Published items');
select extensions.is((select count(*)::integer from public.match_agent_knowledge(current_setting('test.sw')::uuid,current_setting('test.sb')::uuid,current_setting('test.svec')::extensions.vector)),1,'Selected mode cannot retrieve unrelated Published items');
select extensions.is((select id from public.match_agent_knowledge(current_setting('test.sw')::uuid,current_setting('test.sb')::uuid,current_setting('test.svec')::extensions.vector)),current_setting('test.k1')::uuid,'Selected Agent receives only selected factual authority');
select public.change_knowledge_status(current_setting('test.sw')::uuid,current_setting('test.k1')::uuid,'archived');
select extensions.is((select count(*)::integer from public.match_agent_knowledge(current_setting('test.sw')::uuid,current_setting('test.sb')::uuid,current_setting('test.svec')::extensions.vector)),0,'Archival immediately removes runtime authority');
select extensions.is((select count(*)::integer from public.agent_knowledge_items where agent_id=current_setting('test.sb')::uuid),2,'Unavailable item bindings remain for later review');
select public.change_knowledge_status(current_setting('test.sw')::uuid,current_setting('test.k1')::uuid,'draft');
do $$ begin perform set_config('test.krevision',(select revision::text from public.knowledge_items where id=current_setting('test.k1')::uuid),true); end $$;
set local role service_role;
set local request.jwt.claims='{"role":"service_role"}';
select public.publish_knowledge_item('af444444-4444-4444-8444-444444444444',current_setting('test.sw')::uuid,current_setting('test.k1')::uuid,current_setting('test.krevision')::integer,current_setting('test.svec')::extensions.vector);
set local role authenticated;
set local request.jwt.claims='{"sub":"af444444-4444-4444-8444-444444444444","role":"authenticated"}';
select extensions.is((select count(*)::integer from public.match_agent_knowledge(current_setting('test.sw')::uuid,current_setting('test.sb')::uuid,current_setting('test.svec')::extensions.vector)),1,'Republished selected item becomes eligible again');
select public.change_knowledge_status(current_setting('test.sw')::uuid,current_setting('test.k1')::uuid,'draft');
select extensions.is((select count(*)::integer from public.match_agent_knowledge(current_setting('test.sw')::uuid,current_setting('test.sb')::uuid,current_setting('test.svec')::extensions.vector)),0,'Unpublishing immediately removes runtime authority');
select * from extensions.finish();
rollback;
